const mineflayer = require('mineflayer')
const readline = require('readline')
const { pathfinder, Movements, goals } = require('mineflayer-pathfinder')
const { Vec3 } = require('vec3')
 
             let bot, afkInterval, attackInterval, hanhDongInterval, antiAternosInterval
              let dangChuDongStop = false, dangAutoAttack = false, dangPhaBlock = false, dangAn = false
              let dangDaoGo = false, dangDiDao = false, dangDiChuyenDenBlock = false, dangTimRuong = false
              let dangAutoQuang = false, dangBoChay = false
              let blockMucTieu = null, soLuongCanPha = 0, soLuongDaPha = 0
              let keThuMucTieu = null

              const rl = readline.createInterface({ input: process.stdin, output: process.stdout })

              function huyTatCaHanhDong() {
                if (afkInterval) clearInterval(afkInterval)
                  if (attackInterval) clearInterval(attackInterval)
                    if (hanhDongInterval) clearInterval(hanhDongInterval)
                      if (antiAternosInterval) clearInterval(antiAternosInterval)
                        dangPhaBlock = false; dangAutoAttack = false; blockMucTieu = null; dangAn = false
                          dangDaoGo = false; dangDiDao = false; dangDiChuyenDenBlock = false; keThuMucTieu = null; dangTimRuong = false; dangAutoQuang = false; dangBoChay = false
                            if (bot && bot.pathfinder) { try { bot.pathfinder.stop(); bot.clearControlStates() } catch(e){} }
                            }

                            function createBot() {
                              dangChuDongStop = false; dangPhaBlock = false; blockMucTieu = null; dangAn = false
                                dangDaoGo = false; dangDiDao = false; dangDiChuyenDenBlock = false; keThuMucTieu = null; dangTimRuong = false; dangAutoQuang = false; dangBoChay = false

                                  console.log(`\n[HỆ THỐNG] Đang kết nối tới server CRACK ${config.host}:${config.port}...`)
                                    bot = mineflayer.createBot(config)
                                      bot.loadPlugin(pathfinder)

                                        bot.on('spawn', () => {
                                            console.log(`[THÀNH CÔNG] Bot "${bot.username}" đã vào server thành công!`)
                                                HienThiMenuHuongDan()

                                                    const mcData = require('minecraft-data')(bot.version)
                                                        const defaultMovements = new Movements(bot, mcData)
                                                            defaultMovements.canDig = true
                                                                bot.pathfinder.setMovements(defaultMovements)

                                                                    dangDiDao = true

                                                                        clearInterval(hanhDongInterval)
                                                                            hanhDongInterval = setInterval(async () => {
                                                                                  if (!bot || !bot.entity) return

                                                                                        if (dangBoChay) {
                                                                                                if (!bot.pathfinder.isMoving()) {
                                                                                                          console.log('[TỰ VỆ] Đã chạy thoát đến khu vực an toàn. Quay lại đi dạo.')
                                                                                                                    dangBoChay = false; dangDiDao = true
                                                                                                                            }
                                                                                                                                    return
                                                                                                                                          }

                                                                                                                                                if (keThuMucTieu) {
                                                                                                                                                        const khoangCachQuai = bot.entity.position.distanceTo(keThuMucTieu.position)
                                                                                                                                                                const quaiChayXa = khoangCachQuai - 15 > 0
                                                                                                                                                                        if (!keThuMucTieu.isValid || keThuMucTieu.metadata <= 0 || quaiChayXa) {
                                                                                                                                                                                  console.log('[CHIẾN ĐẤU] Kẻ thù đã bị hạ hoặc chạy xa. Quay lại công việc.')
                                                                                                                                                                                            keThuMucTieu = null; bot.pathfinder.stop()
                                                                                                                                                                                                    } else {
                                                                                                                                                                                                              processDanhTraKeThu(); return
                                                                                                                                                                                                                      }
                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                  if (bot.food < 14 && !dangAn) {
                                                                                                                                                                                                                                          const thucAn = bot.inventory.items().find(item =>
                                                                                                                                                                                                                                                    ['cooked_beef', 'cooked_chicken', 'cooked_porkchop', 'bread', 'apple', 'baked_potato', 'steak'].includes(item.name)
                                                                                                                                                                                                                                                            )
                                                                                                                                                                                                                                                                    if (thucAn) {
                                                                                                                                                                                                                                                                              dangAn = true; bot.pathfinder.stop()
                                                                                                                                                                                                                                                                                        console.log(`[ĂN UỐNG] Đang ăn ${thucAn.name}...`)
                                                                                                                                                                                                                                                                                                  try { await bot.equip(thucAn, 'hand'); await bot.consume() } catch (err) {} finally { dangAn = false }
                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                      if (dangAutoQuang && !dangAn && !dangPhaBlock && !dangDaoGo && !dangTimRuong) { processAutoDaoKhoangSan() }
                                                                                                                                                                                                                                                                                                                            if (dangTimRuong && !dangAn && !dangPhaBlock && !dangDaoGo && !dangAutoQuang) { processAutoLootRuong() }
                                                                                                                                                                                                                                                                                                                                  if (dangPhaBlock && blockMucTieu && soLuongDaPha < soLuongCanPha) { processPhaBlock() }
                                                                                                                                                                                                                                                                                                                                        if (dangDaoGo && !dangAn && !dangPhaBlock) { processAutoChatGo() }
                                                                                                                                                                                                                                                                                                                                              if (dangDiDao && !bot.pathfinder.isMoving() && !dangAn && !dangPhaBlock && !dangDaoGo && !dangTimRuong && !dangAutoQuang) { processDiDaoRandom() }
                                                                                                                                                                                                                                                                                                                                                  }, 1000)

                                                                                                                                                                                                                                                                                                                                                      clearInterval(antiAternosInterval)
                                                                                                                                                                                                                                                                                                                                                          antiAternosInterval = setInterval(() => { if (bot && bot.entity && !keThuMucTieu && !dangBoChay) bot.swingArm('hand') }, 5000)

                                                                                                                                                                                                                                                                                                                                                              clearInterval(afkInterval)
                                                                                                                                                                                                                                                                                                                                                                  afkInterval = setInterval(() => {
                                                                                                                                                                                                                                                                                                                                                                        if (!bot || !bot.entity || dangAutoAttack || dangPhaBlock || dangAn || dangDaoGo || dangDiDao || keThuMucTieu || dangTimRuong || dangAutoQuang || dangBoChay) return
                                                                                                                                                                                                                                                                                                                                                                              bot.setControlState('jump', true); setTimeout(() => { if(bot) bot.setControlState('jump', false) }, 500)
                                                                                                                                                                                                                                                                                                                                                                                  }, 15000)
                                                                                                                                                                                                                                                                                                                                                                                    })

                                                                                                                                                                                                                                                                                                                                                                                      bot.on('entityHurt', (entity) => {
                                                                                                                                                                                                                                                                                                                                                                                          if (!bot || !bot.entity || dangBoChay) return
                                                                                                                                                                                                                                                                                                                                                                                              if (entity.username === bot.username) {
                                                                                                                                                                                                                                                                                                                                                                                                    const danhSachQuaiXungQuanh = Object.values(bot.entities).filter(e => {
                                                                                                                                                                                                                                                                                                                                                                                                            if (e.type !== 'mob' && e.kind !== 'Hostile mobs') return false
                                                                                                                                                                                                                                                                                                                                                                                                                    const cachBot = bot.entity.position.distanceTo(e.position)
                                                                                                                                                                                                                                                                                                                                                                                                                            return cachBot - 8 < 0
                                                                                                                                                                                                                                                                                                                                                                                                                                  })
                                                                                                                                                                                                                                                                                                                                                                                                                                        const soLuongQuai = danhSachQuaiXungQuanh.length
                                                                                                                                                                                                                                                                                                                                                                                                                                              const coTuHaiConTroLen = soLuongQuai - 1 > 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (coTuHaiConTroLen) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.log(`[CẢNH BÁO] Phát hiện có ${soLuongQuai} con quái! Tiến hành bỏ chạy...`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    keThuMucTieu = null; dangPhaBlock = false; dangDaoGo = false; dangTimRuong = false; dangDiDao = false; dangBoChay = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            processBotBoChayKhoiRuong(danhSachQuaiXungQuanh)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const quaiDonLe = bot.nearestEntity(e => (e.type === 'mob' || e.kind === 'Hostile mobs') && bot.entity.position.distanceTo(e.position) <= 6)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (quaiDonLe && !keThuMucTieu) { keThuMucTieu = quaiDonLe; console.log(`[TỰ VỆ] Bị 1 con ${quaiDonLe.name} cắn! Chém trả...`) }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                bot.on('chat', (username, message) => console.log(`[MINECRAFT CHAT] <${username}>: ${message}`))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  bot.on('death', () => { console.log('[HỆ THỐNG] Bot chết! Chờ hồi sinh...'); if (bot && bot.pathfinder) bot.pathfinder.stop(); setTimeout(() => { if (bot) { try { bot.respawn(); dangPhaBlock = false; dangDaoGo = false; keThuMucTieu = null; dangTimRuong = false; dangBoChay = false; dangDiDao = true } catch (err) {} } }, 2500) })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // HỆ THỐNG ÉP KẾT NỐI LẠI ĐÚNG CHÍNH XÁC 15 GIÂY (15000 MS)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      bot.on('end', (reason) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          console.log(`[CẢNH BÁO] Mất kết nối: ${reason}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              huyTatCaHanhDong();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (dangChuDongStop) { console.log('[HỆ THỐNG] Đã chủ động tắt bot.'); process.exit(0) }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      console.log('[HỆ THỐNG] Đang đếm ngược đúng 15 giây để tự động kết nối lại...');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          bot = null // Giải phóng hoàn toàn luồng bot cũ tránh treo ram
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              setTimeout(createBot, 15000)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  bot.on('error', (err) => console.log(`[LỖI MẠNG] ${err.message}`))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  function processBotBoChayKhoiRuong(danhSachQuai) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!bot || danhSachQuai.length === 0) return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const viTriBot = bot.entity.position
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let tongVectorX = 0, tongVectorZ = 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          for (const quai of danhSachQuai) { tongVectorX += quai.position.x - viTriBot.x; tongVectorZ += quai.position.z - viTriBot.z }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const huongX = tongVectorX / danhSachQuai.length, huongZ = tongVectorZ / danhSachQuai.length
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const xAnToan = viTriBot.x - (huongX !== 0 ? (huongX / Math.abs(huongX)) * 16 : (Math.random() * 20 - 10))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const zAnToan = viTriBot.z - (huongZ !== 0 ? (huongZ / Math.abs(huongZ)) * 16 : (Math.random() * 20 - 10))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const diemChayTron = new Vec3(xAnToan, viTriBot.y, zAnToan)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.log(`[TỰ VỆ] Đang bỏ chạy trốn đàn quái sang hướng: X:${Math.round(xAnToan)} Z:${Math.round(zAnToan)}`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      bot.pathfinder.setGoal(new goals.GoalNear(diemChayTron.x, diemChayTron.y, diemChayTron.z, 2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      async function processAutoDaoKhoangSan() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!bot || dangDiChuyenDenBlock) return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const mcData = require('minecraft-data')(bot.version)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const idQuangCanTim = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mcData.blocksByName['iron_ore']?.id, mcData.blocksByName['deepslate_iron_ore']?.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    mcData.blocksByName['coal_ore']?.id, mcData.blocksByName['deepslate_coal_ore']?.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        mcData.blocksByName['diamond_ore']?.id, mcData.blocksByName['deepslate_diamond_ore']?.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            mcData.blocksByName['gold_ore']?.id, mcData.blocksByName['deepslate_gold_ore']?.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                mcData.blocksByName['copper_ore']?.id, mcData.blocksByName['deepslate_copper_ore']?.id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ].filter(id => id !== undefined)

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const quangBlock = bot.findBlock({ matching: idQuangCanTim, maxDistance: 25, useExtraInfo: false })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!quangBlock) return

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const khoangCach = bot.entity.position.distanceTo(quangBlock.position)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const tamDaoXa = khoangCach - 4
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (tamDaoXa > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        dangDiChuyenDenBlock = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              console.log(`[AUTO-MINING] Thấy quặng ${quangBlock.name} tại X:${quangBlock.position.x} Y:${quangBlock.position.y}. Đang chạy lại...`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    await bot.pathfinder.goto(new goals.GoalNear(quangBlock.position.x, quangBlock.position.y, quangBlock.position.z, 2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          dangDiChuyenDenBlock = false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (bot.entity.position.distanceTo(quangBlock.position) > 4.5) return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      await bot.lookAt(quangBlock.position.offset(0.5, 0.5, 0.5))

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          let cupXin = bot.inventory.items().find(i => i.name === 'netherite_pickaxe' || i.name === 'diamond_pickaxe' || i.name === 'iron_pickaxe' || i.name === 'stone_pickaxe' || i.name === 'wooden_pickaxe')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (cupXin && bot.heldItem?.name !== cupXin.name) await bot.equip(cupXin, 'hand')

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  console.log(`[ĐÀO] Đang khai thác khối ${quangBlock.name}...`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      await bot.dig(quangBlock)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (err) { dangDiChuyenDenBlock = false }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let dangMoRuong = false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        async function processAutoLootRuong() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (dangMoRuong || !bot) return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            dangMoRuong = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const mcData = require('minecraft-data')(bot.version)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const ruongBlock = bot.findBlock({ matching: [mcData.blocksByName['chest'].id, mcData.blocksByName['trapped_chest'].id], maxDistance: 20 })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!ruongBlock) { dangMoRuong = false; return }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await bot.pathfinder.goto(new goals.GoalNear(ruongBlock.position.x, ruongBlock.position.y, ruongBlock.position.z, 2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            await bot.lookAt(ruongBlock.position.offset(0.5, 0.5, 0.5))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const chest = await bot.openChest(ruongBlock)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const itemsTrongRuong = chest.containerItems()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (itemsTrongRuong.length === 0) { chest.close(); dangMoRuong = false; return }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let daLayTool = false, daLayBlock = false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (const item of itemsTrongRuong) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const tenVatPham = item.name.toLowerCase()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const laTool = ['pickaxe', 'axe', 'shovel', 'sword', 'hoe', 'helmet', 'chestplate', 'leggings', 'boots', 'bow', 'shield'].some(keyword => tenVatPham.includes(keyword))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (laTool && !daLayTool) { await chest.withdraw(item.type, null, 1); daLayTool = true; await bot.sleep(300) }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const laBlockStack = ['stone', 'cobblestone', 'dirt', 'grass', 'planks', 'wood', 'sand', 'gravel', 'brick', 'deepslate'].some(keyword => tenVatPham.includes(keyword))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (laBlockStack && !daLayBlock && item.count >= 1) { const soLuongLay = Math.min(item.count, 64); await chest.withdraw(item.type, null, soLuongLay); daLayBlock = true; await bot.sleep(300) }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (daLayTool && daLayBlock) break
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            chest.close(); dangTimRuong = false; dangDiDao = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              } catch (err) { if (typeof chest !== 'undefined') chest.close() } finally { dangMoRuong = false }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function batDauPhaBlock(tenBlock, soLuong) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const mcData = require('minecraft-data')(bot.version)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const targetBlockType = mcData.blocksByName[tenBlock]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!targetBlockType) { console.log(`[LỖI] Tên block "${tenBlock}" sai!`); return }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      blockMucTieu = targetBlockType.id; soLuongCanPha = soLuong; soLuongDaPha = 0; dangPhaBlock = true; dangDiChuyenDenBlock = false; dangDiDao = false; dangTimRuong = false; dangAutoQuang = false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      async function processPhaBlock() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!bot || dangAn || dangDiChuyenDenBlock) return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const block = bot.findBlock({ matching: blockMucTieu, maxDistance: 25, useExtraInfo: false })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!block) { dangPhaBlock = false; dangDiDao = true; return }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const khoangCach = bot.entity.position.distanceTo(block.position)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (khoangCach - 4 > 0) { dangDiChuyenDenBlock = true; await bot.pathfinder.goto(new goals.GoalNear(block.position.x, block.position.y, block.position.z, 2)); dangDiChuyenDenBlock = false }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (khoangCach - 4.5 > 0) return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            await bot.lookAt(block.position.offset(0.5, 0.5, 0.5))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let dungCu = bot.inventory.items().find(i => i.name.includes('pickaxe') || i.name.includes('shovel'))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (dungCu) await bot.equip(dungCu, 'hand')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await bot.dig(block)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            soLuongDaPha++
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (soLuongDaPha >= soLuongCanPha) { dangPhaBlock = false; dangDiDao = true }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } catch (err) { dangDiChuyenDenBlock = false }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  let dangXuLyGo = false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  async function processAutoChatGo() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (dangXuLyGo || !bot) return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      dangXuLyGo = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const danhSachGo = bot.findBlocks({ matching: (block) => block.name.includes('_log') || block.name === 'log', maxDistance: 25, count: 1 })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (danhSachGo.length === 0) { dangXuLyGo = false; dangDaoGo = false; dangDiDao = true; return }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const viTriGo = danhSachGo; const blockGo = bot.blockAt(viTriGo)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  await bot.pathfinder.goto(new goals.GoalNear(viTriGo.x, viTriGo.y, viTriGo.z, 2))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      await bot.lookAt(viTriGo.offset(0.5, 0.5, 0.5))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          let riu = bot.inventory.items().find(i => i.name.includes('axe'))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (riu) await bot.equip(riu, 'hand')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  await bot.dig(blockGo)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } finally { dangXuLyGo = false }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      function processDiDaoRandom() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const toaDoBot = bot.entity.position
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const xNgauNhien = toaDoBot.x + (Math.random() * 48 - 24)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const zNgauNhien = toaDoBot.z + (Math.random() * 48 - 24)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const mucTieu = new Vec3(xNgauNhien, toaDoBot.y, zNgauNhien)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log(`[ĐI LUNG TUNG] Đang tìm kiếm tài nguyên: X:${Math.round(xNgauNhien)} Z:${Math.round(zNgauNhien)}`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  bot.pathfinder.setGoal(new goals.GoalNear(mucTieu.x, mucTieu.y, mucTieu.z, 1.5))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  async function processDanhTraKeThu() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!bot || !keThuMucTieu) return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const khoangCach = bot.entity.position.distanceTo(keThuMucTieu.position)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let vuKhi = bot.inventory.items().find(i => i.name.includes('sword') || i.name.includes('axe'))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (vuKhi && bot.heldItem?.name !== vuKhi.name) await bot.equip(vuKhi, 'hand').catch(() => {})
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (khoangCach - 3 > 0) { bot.pathfinder.setGoal(new goals.GoalNear(keThuMucTieu.position.x, keThuMucTieu.position.y, keThuMucTieu.position.z, 1.5)) }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              else { bot.pathfinder.stop(); await bot.lookAt(keThuMucTieu.position.offset(0, 1, 0)); bot.attack(keThuMucTieu) }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function HienThiMenuHuongDan() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log(`\n================ BẢNG LỆNH ĐIỀU KHIỂN CỐ ĐỊNH 15S REJOIN ================`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  console.log(`* REJOIN CỐ ĐỊNH: Khi bị mất kết nối, bot đếm ngược đúng 15 giây là tự vào lại server!`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.log(`* "mine"            : BẬT chế độ TỰ ĐỘNG ĐI DÒ VÀ ĐÀO mọi loại khoáng sản`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      console.log(`* "stopmine"        : TẮT chế độ đào khoáng sản`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.log(`* "chest" / "stopchest"       : Bật/Tắt tự động đi loot rương người khác`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          console.log(`* "phablock <tên> <số_lượng>" : Đào thủ công khối chỉ định`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.log(`* "go" / "stopgo"             : Bật/Tắt tự tìm chặt gỗ`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              console.log(`* "say <nội dung>"            : Ép bot gõ lời chat vào game`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log(`===========================================================================\n`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                rl.on('line', (line) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const ghiChu = line.trim(); if (!ghiChu) return
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const args = ghiChu.split(' '); const command = args.toLowerCase()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (command === 'say') { if (!bot) return; const noiDungChat = ghiChu.substring(4).trim(); if (noiDungChat) bot.chat(noiDungChat); return }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (command === 'mine') { dangAutoQuang = true; dangDiDao = true; dangDaoGo = false; dangTimRuong = false; console.log('[HỆ THỐNG] Đã BẬT chế độ tự động dò quặng!') }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          else if (command === 'stopmine') { dangAutoQuang = false; bot.pathfinder.stop(); console.log('[HỆ THỐNG] Đã TẮT chế độ đào khoáng sản.') }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (command === 'chest') { dangTimRuong = true; dangDiDao = true; dangDaoGo = false; dangAutoQuang = false; console.log('[HỆ THỐNG] Đã BẬT chế độ tự đi tìm luộc rương!') }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              else if (command === 'stopchest') { dangTimRuong = false; bot.pathfinder.stop(); console.log('[HỆ THỐNG] Đã TẮT chế độ tìm rương.') }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (command === 'go') { dangDaoGo = true; dangDiDao = false; dangTimRuong = false; dangAutoQuang = false; console.log('[HỆ THỐNG] Bật tự động chặt gỗ.') }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  else if (command === 'stopgo') { dangDaoGo = false; dangDiDao = true; console.log('[HỆ THỐNG] Tắt chặt gỗ.') }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    else if (command === 'walk') { dangDiDao = true; dangDaoGo = false; dangTimRuong = false; dangAutoQuang = false; console.log('[HỆ THỐNG] Bật đi dạo ngẫu nhiên.') }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      else if (command === 'stopwalk') { dangDiDao = false; bot.pathfinder.stop(); console.log('[HỆ THỐNG] Dừng di chuyển.') }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else if (command === 'phablock') { const name = args; const sl = parseInt(args); if (name && !isNaN(sl)) { batDauPhaBlock(name, sl) } }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          else if (command === 'stoppha') { dangPhaBlock = false; dangDiDao = true; console.log('[HỆ THỐNG] Ngừng đào.') }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            else if (command === 'stop' || command === 'out') { dangChuDongStop = true; huyTatCaHanhDong(); if (bot) { bot.chat('Off đây!'); setTimeout(() => bot.quit(), 500) } else process.exit(0) }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            })

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            createBot()
